package com.nexttv;
import android.app.*;import android.content.*;import android.os.*;import android.view.KeyEvent;import android.view.accessibility.AccessibilityNodeInfo;
public class CompatibilityInstrumentation extends com.nexttv.support.NextTvInstrumentation {

 @Override public void onCreate(Bundle b){super.onCreate(b);singleColumn=b!=null&&"true".equals(b.getString("singleColumn"));start();}

 private void launch()throws Exception{activity=startActivitySync(new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_LAUNCHER).setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));text("频道分类：");SystemClock.sleep(2300);}
 private void closeEditor()throws Exception{key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(tree().contains("保存"))key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(250);}
 private void pass(String name){passed++;results.append("PASS ").append(name).append('\n');Bundle b=new Bundle();b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}


 private void reopen(){try(android.os.ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("am start -a android.intent.action.MAIN -c android.intent.category.LAUNCHER -f 0x10200000 -n com.nexttv/com.nexttv.core.tv.TvActivity")){java.io.FileInputStream input=new java.io.FileInputStream(fd.getFileDescriptor());byte[] buffer=new byte[1024];while(input.read(buffer)>=0){}}catch(Exception e){throw new RuntimeException(e);}}
 private void shot(String name)throws Exception{android.graphics.Bitmap image=getUiAutomation().takeScreenshot();if(image!=null){try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getFilesDir(),"fix13-"+name+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();}}

 private void export(String name,byte[] data,String mime,String suffix)throws Exception{String file="nexttv-audit-"+name+"-"+SystemClock.uptimeMillis()+suffix;android.content.ContentValues v=new android.content.ContentValues();v.put(android.provider.MediaStore.MediaColumns.DISPLAY_NAME,file);v.put(android.provider.MediaStore.MediaColumns.MIME_TYPE,mime);v.put(android.provider.MediaStore.MediaColumns.RELATIVE_PATH,"Download/NextTVAudit");android.net.Uri uri=getTargetContext().getContentResolver().insert(android.net.Uri.parse("content://media/external/downloads"),v);try(java.io.OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){out.write(data);}Bundle b=new Bundle();b.putString("stream","EXPORT "+file+"\n");sendStatus(0,b);}
 private String nodes(AccessibilityNodeInfo n){if(n==null)return "";android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);String t=n.getText()==null?"":n.getText().toString();String d=n.getContentDescription()==null?"":n.getContentDescription().toString();StringBuilder b=new StringBuilder();if(!t.isEmpty()||!d.isEmpty()||n.isFocusable())b.append("text=").append(t).append(" desc=").append(d).append(" selected=").append(n.isSelected()).append(" focus=").append(n.isFocused()).append(" focusable=").append(n.isFocusable()).append(" click=").append(n.isClickable()).append(" bounds=").append(r).append('\n');for(int i=0;i<n.getChildCount();i++)b.append(nodes(n.getChild(i)));return b.toString();}
 private void record(String name)throws Exception{SystemClock.sleep(350);android.graphics.Bitmap image=getUiAutomation().takeScreenshot();java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes);image.recycle();export(name,bytes.toByteArray(),"image/png",".png");export(name,nodes(getUiAutomation().getRootInActiveWindow()).getBytes(java.nio.charset.StandardCharsets.UTF_8),"text/plain",".txt");}
 private void desc(String description)throws Exception{AccessibilityNodeInfo n=getUiAutomation().getRootInActiveWindow();java.util.ArrayDeque<AccessibilityNodeInfo> q=new java.util.ArrayDeque<>();q.add(n);while(!q.isEmpty()){n=q.removeFirst();if(description.contentEquals(n.getContentDescription()==null?"":n.getContentDescription())){while(!n.isClickable())n=n.getParent();n.performAction(AccessibilityNodeInfo.ACTION_CLICK);SystemClock.sleep(300);return;}for(int i=0;i<n.getChildCount();i++)if(n.getChild(i)!=null)q.add(n.getChild(i));}throw new IllegalStateException("Missing description "+description);}
 private android.content.SharedPreferences prefs;private java.util.Map<String,?> saved;
 private void restore(){if(saved==null)return;if(activity!=null&&!activity.isFinishing()){runOnMainSync(()->activity.finish());waitForIdleSync();}android.content.SharedPreferences.Editor e=prefs.edit().clear();for(java.util.Map.Entry<String,?> entry:saved.entrySet()){String k=entry.getKey();Object v=entry.getValue();if(v instanceof String)e.putString(k,(String)v);else if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else if(v instanceof Integer)e.putInt(k,(Integer)v);else if(v instanceof Long)e.putLong(k,(Long)v);else if(v instanceof Float)e.putFloat(k,(Float)v);else if(v instanceof java.util.Set)e.putStringSet(k,(java.util.Set<String>)v);}e.commit();saved=null;}

 private android.graphics.Rect bounds(String label)throws Exception{AccessibilityNodeInfo n=find(label,false,getUiAutomation().getRootInActiveWindow());if(n==null)throw new IllegalStateException("Missing "+label);while(!n.isFocusable())n=n.getParent();android.graphics.Rect r=new android.graphics.Rect();n.getBoundsInScreen(r);return r;}
 private void sameBounds(String label,android.graphics.Rect before)throws Exception{android.graphics.Rect after=bounds(label);if(Math.abs(after.width()-before.width())>1||Math.abs(after.height()-before.height())>1||Math.abs(after.left-before.left)>1||Math.abs(after.top-before.top)>1)throw new IllegalStateException("Focus scaled/moved "+label+" "+before+" → "+after);}

 private boolean hasDesc(String t,AccessibilityNodeInfo n){if(n==null)return false;if(t.contentEquals(n.getContentDescription()==null?"":n.getContentDescription()))return true;for(int i=0;i<n.getChildCount();i++)if(hasDesc(t,n.getChild(i)))return true;return false;}
 private void noFavoriteActions(){if(tree().contains("管理播放源")||tree().contains("添加订阅")||hasDesc("重新拉取",getUiAutomation().getRootInActiveWindow()))throw new IllegalStateException("Source actions remain in Favorites");}
 private AccessibilityNodeInfo editable(AccessibilityNodeInfo n){if(n==null)return null;if(n.isEditable())return n;for(int i=0;i<n.getChildCount();i++){AccessibilityNodeInfo r=editable(n.getChild(i));if(r!=null)return r;}return null;}
 @Override public void onStart(){try{
 prefs=getTargetContext().getSharedPreferences("nexttv",0);prefs.edit().putBoolean("start_live",false).putBoolean("auto_update",false).putBoolean("auto_update_epg",false).putBoolean("previews",false).putInt("preload_mode",0).commit();activity=startActivitySync(new Intent().setClassName("com.nexttv","com.nexttv.core.tv.TvActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));SystemClock.sleep(1200);for(int prompt=0;prompt<30;prompt++){if(tree().contains("Got it")){click("Got it");break;}if(tree().contains("全部频道"))break;SystemClock.sleep(300);}text("全部频道");await("initial channels state",()->tree().contains("尚未添加订阅")||tree().contains("CCTV1综合"));
 if(tree().contains("尚未添加订阅")){focus("频道");key(KeyEvent.KEYCODE_DPAD_DOWN);await("empty Add remote focus",()->focus().contains("添加订阅"));key(KeyEvent.KEYCODE_ENTER);text("确认添加");key(KeyEvent.KEYCODE_ENTER);await("editable",()->editable(getUiAutomation().getRootInActiveWindow())!=null);Bundle value=new Bundle();value.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,"兼容测试,http://192.0.2.115:8787/live.m3u");if(!editable(getUiAutomation().getRootInActiveWindow()).performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,value))throw new IllegalStateException("Enter source");click("确认添加");await("real import",()->tree().contains("CCTV1综合"));pass("API"+android.os.Build.VERSION.SDK_INT+" remote/keyboard empty-state import uses real subscription");}
 focus("频道");key(KeyEvent.KEYCODE_DPAD_LEFT);if(!focus().contains("频道"))throw new IllegalStateException("Cold channel Left wrapped");key(KeyEvent.KEYCODE_DPAD_RIGHT);text("我的收藏");key(KeyEvent.KEYCODE_DPAD_RIGHT);text("节目单地址");key(KeyEvent.KEYCODE_DPAD_DOWN);await("first setting",()->focus().contains("节目单地址"));for(int i=0;i<7;i++)key(KeyEvent.KEYCODE_DPAD_DOWN);key(KeyEvent.KEYCODE_ESCAPE);await("settings Back top",()->focus().equals("设置"));key(KeyEvent.KEYCODE_DPAD_DOWN);await("settings reset first",()->focus().contains("节目单地址"));key(KeyEvent.KEYCODE_ESCAPE);focus("频道");pass("three-menu boundaries and settings Back/reset navigation");
 click("CCTV1综合");SystemClock.sleep(7000);key(KeyEvent.KEYCODE_MENU);text("音轨");text("主页");key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_ENTER);text("向\n右\n查\n看\n节\n目\n单");key(KeyEvent.KEYCODE_DPAD_LEFT);text("全部频道");key(KeyEvent.KEYCODE_DPAD_RIGHT);key(KeyEvent.KEYCODE_DPAD_RIGHT);text("日期");key(KeyEvent.KEYCODE_ESCAPE);SystemClock.sleep(400);if(tree().contains("日期"))throw new IllegalStateException("Escape retained guide");pass("actual live URL opened, quick menu and group-channel-guide association operate");
 android.graphics.Bitmap image=getUiAutomation().takeScreenshot();java.io.File dest=new java.io.File(getTargetContext().getExternalFilesDir(null),"compat-api"+android.os.Build.VERSION.SDK_INT+".png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(dest)){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}image.recycle();
 if(tree().contains("CCTV1综合"))key(KeyEvent.KEYCODE_ESCAPE);key(KeyEvent.KEYCODE_BACK);text("再按一次退出播放");key(KeyEvent.KEYCODE_BACK);text("频道分类：");focus("频道");key(KeyEvent.KEYCODE_BACK);text("再按一次退出");pass("player and application double-Back confirmation");
 android.app.ActivityManager am=(android.app.ActivityManager)getTargetContext().getSystemService(android.content.Context.ACTIVITY_SERVICE);android.app.ActivityManager.MemoryInfo mem=new android.app.ActivityManager.MemoryInfo();am.getMemoryInfo(mem);android.os.Debug.MemoryInfo pss=new android.os.Debug.MemoryInfo();android.os.Debug.getMemoryInfo(pss);results.append("DEVICE api=").append(android.os.Build.VERSION.SDK_INT).append(" memoryClassMB=").append(am.getMemoryClass()).append(" lowRam=").append(am.isLowRamDevice()).append(" totalMemoryBytes=").append(mem.totalMem).append(" availableMemoryBytes=").append(mem.availMem).append(" pssKB=").append(pss.getTotalPss()).append(" maxHeapBytes=").append(Runtime.getRuntime().maxMemory()).append(" cores=").append(Runtime.getRuntime().availableProcessors()).append('\n');
 runOnMainSync(()->activity.finish());Bundle b=new Bundle();b.putString("stream",results.toString());finish(Activity.RESULT_OK,b);
 }catch(Throwable t){try{if(android.os.Build.VERSION.SDK_INT>=29)record("compat-api"+android.os.Build.VERSION.SDK_INT+"-failure");}catch(Throwable ignored){}if(activity!=null)runOnMainSync(()->activity.finish());Bundle b=new Bundle();b.putString("stream",android.util.Log.getStackTraceString(t));finish(Activity.RESULT_CANCELED,b);}}
}
